function getCellSet(cellId) {
  const cell = CELLS[cellId];
  return cell?.setId ?? null;
}
function forwardToNearestFate(fromPos) {
  const fatePositions = CELLS.filter((c2) => c2.type === "fate").map((c2) => c2.id).sort((a2, b2) => a2 - b2);
  for (const pos of fatePositions) {
    if (pos > fromPos) return pos;
  }
  return fatePositions[0] + CELL_COUNT;
}
