function getInitialSkillTree() {
  const tree = {};
  for (const id2 of SKILL_IDS) {
    tree[id2] = 0;
  }
  return tree;
}
function getSkillValue(skillTree, skillId) {
  if (!skillTree) return 0;
  const level = skillTree[skillId] ?? 0;
  if (level <= 0) return 0;
  const config2 = SKILLS[skillId];
  const effect = config2.effects.find((e3) => e3.level === level);
  return effect?.value ?? 0;
}
