function encodeMapToBase64(cells) {
  return btoa(JSON.stringify(cells));
}
function decodeMapFromBase64(base642) {
  return JSON.parse(atob(base642));
}
function validateMap(cells) {
  const errors = [];
  if (cells.length !== CELL_COUNT) errors.push(`必須有 ${CELL_COUNT} 格`);
  const startCount = cells.filter((c2) => c2.type === "start").length;
  if (startCount !== 1) errors.push(`必須有 1 個起點（當前 ${startCount} 個）`);
  const detentionCount = cells.filter((c2) => c2.type === "detention").length;
  if (detentionCount !== 1) errors.push(`必須有 1 個禁閉區（當前 ${detentionCount} 個）`);
  const fateCount = cells.filter((c2) => c2.type === "fate").length;
  if (fateCount < 2) errors.push(`至少有 2 個命運區（當前 ${fateCount} 個）`);
  const chanceCount = cells.filter((c2) => c2.type === "chance").length;
  if (chanceCount < 2) errors.push(`至少有 2 個機會區（當前 ${chanceCount} 個）`);
  return {
    valid: errors.length === 0,
    errors
  };
}
