  seller.money += price;
  seller.itemSellCount = sellCount + 1;
  newState.logs.push(makeLog(logType, `【商店】 【黑市】${seller.name} 將 ${ITEMS[itemType].name} 賣給 ${buyer.name}，成交價 ${price} 元（剩餘 ${maxSells - sellCount - 1} 次）`));
